static const char * const kLCProxyConsoleHTML =
"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>LiveProxy Tailscale 控制台</title>\n<style>\n:root { color-scheme: dark; }\nbody { margin:0; font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif; background:#0d1117; color:#e6edf3; }\nheader { padding:18px 16px 10px; border-bottom:1px solid #21262d; }\nheader h1 { margin:0; font-size:20px; }\nheader .sub { color:#8b949e; font-size:13px; margin-top:4px; }\nmain { padding:16px; max-width:760px; margin:0 auto; }\n.card { background:#161b22; border:1px solid #30363d; border-radius:12px; padding:16px; margin-bottom:14px; }\n.card h2 { margin:0 0 12px; font-size:16px; }\n.row { display:flex; align-items:flex-start; justify-content:space-between; gap:12px; padding:8px 0; border-bottom:1px solid #21262d; }\n.row:last-child { border-bottom:none; }\n.k { color:#8b949e; flex:0 0 auto; }\n.v { font-weight:600; word-break:break-all; overflow-wrap:anywhere; text-align:right; min-width:0; }\ninput[type=text], input[type=number] { background:#0d1117; border:1px solid #30363d; color:#e6edf3; border-radius:8px; padding:8px 10px; width:100%; box-sizing:border-box; }\nbutton { background:#238636; color:#fff; border:none; border-radius:8px; padding:10px 14px; font-size:15px; cursor:pointer; }\nbutton.secondary { background:#30363d; }\n.switch { position:relative; width:48px; height:26px; display:inline-block; flex:0 0 auto; }\n.switch input { opacity:0; width:0; height:0; }\n.slider { position:absolute; cursor:pointer; inset:0; background:#30363d; border-radius:26px; transition:.2s; }\n.slider:before { content:\"\"; position:absolute; height:20px; width:20px; left:3px; top:3px; background:#fff; border-radius:50%; transition:.2s; }\n.switch input:checked + .slider { background:#238636; }\n.switch input:checked + .slider:before { transform:translateX(22px); }\ntable { width:100%; border-collapse:collapse; font-size:13px; }\nth,td { text-align:right; padding:6px 8px; border-bottom:1px solid #21262d; }\nth:first-child,td:first-child { text-align:left; }\n.msg { color:#58a6ff; font-size:13px; margin-top:8px; min-height:18px; }\n.badge { display:inline-block; padding:2px 8px; border-radius:10px; font-size:12px; }\n.badge.on { background:#1f6feb33; color:#58a6ff; }\n.badge.off { background:#f8514933; color:#f85149; }\n.tabs { display:flex; gap:8px; padding:10px 16px 0; max-width:760px; margin:0 auto; border-bottom:1px solid #21262d; }\n.tab { padding:8px 14px; border-radius:8px 8px 0 0; color:#8b949e; cursor:pointer; font-size:14px; }\n.tab.active { color:#e6edf3; background:#161b22; border:1px solid #30363d; border-bottom-color:#161b22; }\n.tabpage { display:none; }\n.tabpage.active { display:block; }\nselect { background:#0d1117; border:1px solid #30363d; color:#e6edf3; border-radius:8px; padding:8px 10px; width:100%; box-sizing:border-box; }\n</style>\n</head>\n<body>\n<header>\n  <h1>LiveProxy Tailscale 控制台</h1>\n  <div class=\"sub\">LiveContainer 任意 App 走 HTTP 代理 · 10 分钟流量统计</div>\n</header>\n<div class=\"tabs\">\n  <div class=\"tab active\" data-tab=\"proxy\">代理</div>\n  <div class=\"tab\" data-tab=\"tailscale\">Tailscale</div>\n  <div class=\"tab\" data-tab=\"stats\">流量统计</div>\n  <div class=\"tab\" data-tab=\"about\">关于</div>\n</div>\n<main>\n  <div class=\"tabpage active\" id=\"tab-proxy\">\n  <div class=\"card\">\n    <h2>代理控制</h2>\n    <div class=\"row\"><span class=\"k\">启用代理</span>\n      <label class=\"switch\"><input type=\"checkbox\" id=\"proxyEnabled\"><span class=\"slider\"></span></label>\n    </div>\n    <div class=\"row\"><span class=\"k\">丢弃非 TCP（UDP/QUIC）</span>\n      <label class=\"switch\"><input type=\"checkbox\" id=\"blockNonTcp\"><span class=\"slider\"></span></label>\n    </div>\n    <div class=\"row\"><span class=\"k\">调试日志</span>\n      <label class=\"switch\"><input type=\"checkbox\" id=\"debugLogging\"><span class=\"slider\"></span></label>\n    </div>\n    <div class=\"row\"><span class=\"k\">启动显示代理加载横幅</span>\n      <label class=\"switch\"><input type=\"checkbox\" id=\"showProxyBanner\"><span class=\"slider\"></span></label>\n    </div>\n    <div class=\"row\" style=\"display:block\">\n      <label class=\"k\">上游模式</label>\n      <select id=\"proxyMode\">\n        <option value=\"custom\">自定义代理</option>\n        <option value=\"direct\">直连（无代理）</option>\n        <option value=\"kingcard\">王卡代理</option>\n        <option value=\"tailscale\">Tailscale</option>\n      </select>\n      <div class=\"row\"><span class=\"k\">当前生效</span><span class=\"v\" id=\"effectiveMode\">…</span></div>\n      <div id=\"customFields\" style=\"margin-top:10px\">\n        <label class=\"k\">代理类型</label>\n        <input type=\"text\" id=\"proxyType\" value=\"http\">\n        <label class=\"k\">代理地址</label>\n        <input type=\"text\" id=\"proxyHost\" placeholder=\"192.168.1.10\">\n        <label class=\"k\">端口</label>\n        <input type=\"number\" id=\"proxyPort\" placeholder=\"8080\">\n      </div>\n      <div id=\"kingFields\" style=\"display:none;margin-top:10px\">\n        <label class=\"k\">取号手机号</label>\n        <input type=\"text\" id=\"kingPhone\" placeholder=\"18812341234\">\n        <label class=\"k\">Q-Type</label>\n        <input type=\"text\" id=\"kingQType\" placeholder=\"httpcom\">\n        <label class=\"k\">MCCMNC</label>\n        <input type=\"text\" id=\"kingMccmnc\" placeholder=\"46001 或 NULLNULL\">\n        <label class=\"k\">APN</label>\n        <input type=\"text\" id=\"kingApn\" placeholder=\"uninet / 3gnet\">\n        <label class=\"k\">网络类型</label>\n        <input type=\"text\" id=\"kingTypeName\" placeholder=\"MOBILE / WIFI / UNKNOW\">\n        <label class=\"k\">网络子类型</label>\n        <input type=\"number\" id=\"kingSubtype\" placeholder=\"0\">\n        <label class=\"k\">APN 附加信息</label>\n        <input type=\"text\" id=\"kingExtraInfo\" placeholder=\"uninet / 3gwap\">\n        <label class=\"k\">王卡状态</label>\n        <input type=\"number\" id=\"kingCardType\" placeholder=\"1\">\n        <div class=\"row\"><span class=\"k\">非蜂窝网络自动直连</span>\n          <label class=\"switch\"><input type=\"checkbox\" id=\"kingAutoDirectOnNonCellular\"><span class=\"slider\"></span></label>\n        </div>\n        <div class=\"row\"><span class=\"k\">转发器</span><span class=\"v\" id=\"kingRunning\">…</span></div>\n        <div class=\"row\"><span class=\"k\">最近取号</span><span class=\"v\" id=\"kingRefresh\">…</span></div>\n        <div class=\"row\"><span class=\"k\">来源</span><span class=\"v\" id=\"kingSource\">…</span></div>\n        <div class=\"row\"><span class=\"k\">HTTP 代理请求</span><span class=\"v\" id=\"statHttpRequests\">0</span></div>\n        <div class=\"row\"><span class=\"k\">HTTPS CONNECT</span><span class=\"v\" id=\"statHttpsConnects\">0</span></div>\n        <div class=\"row\"><span class=\"k\">直连兜底次数</span><span class=\"v\" id=\"statDirectFallbacks\">0</span></div>\n        <div class=\"row\"><span class=\"k\">凭证刷新次数</span><span class=\"v\" id=\"statRefreshCalls\">0</span></div>\n        <div class=\"msg\" id=\"recentDirectHosts\" style=\"white-space:pre-wrap;font-size:12px;color:#d29922\"></div>\n        <div class=\"msg\" id=\"kingError\"></div>\n        <div class=\"msg\" id=\"kingDiag\" style=\"white-space:pre-wrap;font-size:12px;color:#8b949e\"></div>\n        <div style=\"margin-top:8px\"><button class=\"secondary\" id=\"kingRefreshBtn\">立即刷新凭证</button><div class=\"msg\" id=\"kingManualResult\" style=\"white-space:pre-wrap;font-size:12px;color:#d29922\"></div></div><div class=\"row\" style=\"display:block;margin-top:10px\"><span class=\"k\">最近取号日志（20 条，含所有 App 触发）</span><div id=\"kingRefreshLog\" style=\"margin-top:6px;white-space:pre-wrap;font-size:12px;color:#8b949e;max-height:260px;overflow-y:auto;border:1px solid #30363d;border-radius:8px;padding:8px;\">暂无记录</div></div>\n      </div>\n      <div style=\"margin-top:12px\"><button id=\"saveConfig\">保存并应用</button></div>\n      <div style=\"margin-top:8px\"><button class=\"secondary\" id=\"testProxyBtn\">测试代理出口 IP</button></div>\n      <div class=\"msg\" id=\"proxyTestMsg\"></div>\n      <div class=\"msg\" id=\"proxyTestDetail\" style=\"white-space:pre-wrap;font-size:12px;color:#8b949e\"></div>\n      <div class=\"msg\" id=\"cfgMsg\"></div>\n    </div>\n  </div>\n\n  </div>\n\n  <div class=\"tabpage\" id=\"tab-tailscale\">\n    <div class=\"card\">\n      <h2>Tailscale 控制</h2>\n      <div class=\"row\"><span class=\"k\">运行状态</span><span class=\"v\" id=\"tsRunning\">…</span></div>\n      <div class=\"row\"><span class=\"k\">后端状态</span><span class=\"v\" id=\"tsBackendState\">…</span></div>\n      <div class=\"row\"><span class=\"k\">本地 SOCKS5 端口</span><span class=\"v\" id=\"tsPort\">…</span></div>\n      <div class=\"row\"><span class=\"k\">上次错误</span><span class=\"v\" id=\"tsError\">…</span></div>\n      <div class=\"row\" style=\"display:block;margin-top:6px\">\n        <span class=\"k\">登录链接（AuthURL）</span>\n        <div id=\"tsAuthURL\" style=\"word-break:break-all;font-size:12px;color:#58a6ff;margin-top:4px\">—</div>\n        <button class=\"secondary\" id=\"copyAuthURL\" style=\"margin-top:6px\">复制登录链接</button>\n      </div>\n      <div class=\"row\" style=\"display:block;margin-top:10px\">\n        <label class=\"k\">节点名称（Hostname）</label>\n        <input type=\"text\" id=\"tailscaleHostname\" placeholder=\"lc-tailscale\">\n        <label class=\"k\">Auth Key</label>\n        <input type=\"text\" id=\"tailscaleAuthKey\" placeholder=\"tskey-auth-...\">\n        <label class=\"k\">Control URL</label>\n        <input type=\"text\" id=\"tailscaleControlURL\" placeholder=\"https://control.tailscale.com\">\n        <label class=\"k\">状态目录（留空自动）</label>\n        <input type=\"text\" id=\"tailscaleStateDir\" placeholder=\"/path/to/tailscale\">\n        <div class=\"row\"><span class=\"k\">临时节点（Ephemeral）</span>\n          <label class=\"switch\"><input type=\"checkbox\" id=\"tailscaleEphemeral\"><span class=\"slider\"></span></label>\n        </div>\n        <p class=\"msg\">DERP-only 已固定开启：关闭 P2P 直连/UDP 打洞，所有 Tailscale 外连（含 DERP）走当前王卡代理。</p>\n      </div>\n      <div style=\"margin-top:12px\"><button id=\"saveTailscale\">保存并应用</button></div>\n      <div class=\"msg\" id=\"tsCfgMsg\"></div>\n    </div>\n    <div class=\"card\">\n      <h2>Exit Node</h2>\n      <div class=\"row\"><span class=\"k\">启用 Exit Node</span>\n        <label class=\"switch\"><input type=\"checkbox\" id=\"tailscaleExitNodeEnabled\"><span class=\"slider\"></span></label>\n      </div>\n      <div class=\"row\" style=\"display:block;margin-top:10px\">\n        <label class=\"k\">选择 Exit Node</label>\n        <select id=\"tailscaleExitNodeID\"></select>\n      </div>\n      <div style=\"margin-top:12px\"><button id=\"applyExitNode\">应用 Exit Node</button></div>\n      <div class=\"msg\" id=\"tsExitMsg\"></div>\n    </div>\n  </div>\n\n  <div class=\"tabpage\" id=\"tab-stats\">\n    <div class=\"card\">\n    <h2>流量统计（蜂窝网络）</h2>\n    <div class=\"row\"><span class=\"k\">当前网络</span><span class=\"v\" id=\"net\">…</span></div>\n    <div class=\"row\"><span class=\"k\">累计上传</span><span class=\"v\" id=\"totalUp\">…</span></div>\n    <div class=\"row\"><span class=\"k\">累计下载</span><span class=\"v\" id=\"totalDown\">…</span></div>\n    <div class=\"row\"><span class=\"k\">按 App 明细</span><span class=\"v\" id=\"appList\">…</span></div>\n    <table>\n      <thead><tr><th>时段（10 分钟）</th><th>上传</th><th>下载</th></tr></thead>\n      <tbody id=\"buckets\"></tbody>\n    </table>\n    <div style=\"margin-top:10px\"><button class=\"secondary\" id=\"resetStats\">清空统计</button></div>\n    <div class=\"msg\" id=\"statsMsg\"></div>\n  </div>\n\n  </div>\n\n  <div class=\"tabpage\" id=\"tab-about\">\n  <div class=\"card\">\n    <h2>关于</h2>\n    <div class=\"row\"><span class=\"k\">版本</span><span class=\"v\" id=\"version\">…</span></div>\n    <div class=\"row\"><span class=\"k\">数据目录</span><span class=\"v\" id=\"dataDir\">…</span></div>\n    <div class=\"row\"><span class=\"k\">代理配置</span><span class=\"v\" id=\"confPath\">…</span></div>\n    <div class=\"row\"><span class=\"k\">配置存在</span><span class=\"v\" id=\"confExists\">…</span></div>\n    <div class=\"row\"><span class=\"k\">核心代理数</span><span class=\"v\" id=\"proxyCount\">…</span></div>\n    <div class=\"row\"><span class=\"k\">控制端口</span><span class=\"v\" id=\"port\">…</span></div>\n    <p class=\"msg\">提示：修改代理地址或端口后，建议重启一次被代理 App，确保 WKWebView 等系统组件也使用新配置。</p>\n  </div>\n  </div>\n</main>\n<script>\n\"use strict\";\nconst $ = id => document.getElementById(id);\nconst api = async (path, opts) => {\n  const r = await fetch(path, {headers:{'Content-Type':'application/json'}, ...opts});\n  let j = null; try { j = await r.json(); } catch(e) {}\n  if (!r.ok) return {error:(j&&j.error)||('HTTP '+r.status)};\n  return j;\n};\nlet dirty = false;\nfunction markDirty() { dirty = true; }\nfunction showTab(name) {\n  document.querySelectorAll('.tab').forEach(t => t.classList.toggle('active', t.dataset.tab === name));\n  document.querySelectorAll('.tabpage').forEach(p => p.classList.toggle('active', p.id === 'tab-' + name));\n}\ndocument.querySelectorAll('.tab').forEach(t => {\n  t.addEventListener('click', () => showTab(t.dataset.tab));\n});\nconst fmt = n => {\n  n = Number(n||0);\n  if (n >= 1024*1024*1024) return (n/1024/1024/1024).toFixed(2)+' GB';\n  if (n >= 1024*1024) return (n/1024/1024).toFixed(2)+' MB';\n  if (n >= 1024) return (n/1024).toFixed(1)+' KB';\n  return n+' B';\n};\nconst fmtTime = ts => {\n  const d = new Date(ts*1000);\n  const p = x => String(x).padStart(2,'0');\n  return d.getMonth()+1+'/'+d.getDate()+' '+p(d.getHours())+':'+p(d.getMinutes());\n};\nfunction syncModeUI() {\n  const mode = $('proxyMode').value;\n  $('customFields').style.display = mode === 'custom' ? 'block' : 'none';\n  $('kingFields').style.display = mode === 'kingcard' ? 'block' : 'none';\n  const labels = {custom:'自定义代理', direct:'直连（无代理）', kingcard:'王卡代理', tailscale:'Tailscale'};\n  $('effectiveMode').textContent = labels[mode] || mode || '—';\n}\nasync function loadStatus() {\n  const s = await api('/api/status');\n  if (s.error) { $('cfgMsg').textContent = '状态获取失败: '+s.error; return; }\n  const king = s.king || {};\n  const ts = s.tailscale || {};\n  $('kingRunning').textContent = king.running ? '运行中' : '未运行';\n  $('tsRunning').textContent = ts.starting ? '启动中…' : (ts.running ? '运行中' : '未运行');\n  $('tsBackendState').textContent = ts.backendState || '—';\n  $('tsPort').textContent = ts.proxyPort ? String(ts.proxyPort) : '—';\n  $('tsError').textContent = ts.lastError || '—';\n  const authEl = $('tsAuthURL');\n  if (ts.authURL) {\n    authEl.textContent = ts.authURL;\n    authEl.style.color = '#58a6ff';\n  } else {\n    authEl.textContent = '—';\n  }\n  $('kingRefresh').textContent = king.lastRefresh || '—';\n  $('kingSource').textContent = king.lastSource || '—';\n  const fwStats = s.kingAggregate || {};\n  $('statHttpRequests').textContent = fwStats.httpRequests != null ? fwStats.httpRequests : '0';\n  $('statHttpsConnects').textContent = fwStats.httpsConnects != null ? fwStats.httpsConnects : '0';\n  $('statDirectFallbacks').textContent = fwStats.directFallbacks != null ? fwStats.directFallbacks : '0';\n  $('statRefreshCalls').textContent = fwStats.refreshCalls != null ? fwStats.refreshCalls : '0';\n  const directHosts = (fwStats.recentDirectHosts || []);\n  $('recentDirectHosts').textContent = directHosts.length ? ('最近直连兜底域名(全部App): ' + directHosts.join(', ')) : '';\n  $('kingError').textContent = king.lastError || '';\n  $('kingDiag').textContent = king.lastDiagnostics || '';\n  renderKingLog(king.refreshLog || []);\n  $('version').textContent = s.version || '—';\n  $('dataDir').textContent = s.dataDirectory || '—';\n  $('confPath').textContent = s.proxychainsConfPath || '—';\n  $('confExists').textContent = s.proxychainsConfExists ? '是' : '否';\n  $('proxyCount').textContent = s.proxyCount != null ? String(s.proxyCount) : '—';\n  $('port').textContent = s.serverPort || '—';\n  if (dirty) return;\n  $('proxyEnabled').checked = !!s.proxyEnabled;\n  $('tailscaleHostname').value = s.tailscaleHostname || 'lc-tailscale';\n  $('tailscaleAuthKey').value = s.tailscaleAuthKey || '';\n  $('tailscaleControlURL').value = s.tailscaleControlURL || '';\n  $('tailscaleStateDir').value = s.tailscaleStateDir || '';\n  $('tailscaleEphemeral').checked = s.tailscaleEphemeral != null ? !!s.tailscaleEphemeral : true;\n  $('tailscaleExitNodeEnabled').checked = !!s.tailscaleExitNodeEnabled;\n  renderExitNodes(ts.exitNodes || [], ts.selectedExitNodeID || '');\n  $('blockNonTcp').checked = !!s.blockNonTcp;\n  $('debugLogging').checked = !!s.debugLogging;\n  $('showProxyBanner').checked = s.showProxyBanner != null ? !!s.showProxyBanner : true;\n  $('proxyMode').value = s.proxyMode || 'custom';\n  $('proxyType').value = s.proxyType || 'http';\n  $('proxyHost').value = s.proxyHost || '';\n  $('proxyPort').value = s.proxyPort || '';\n  $('kingPhone').value = s.kingPhone || '18812341234';\n  $('kingQType').value = s.kingQType || 'httpcom';\n  $('kingMccmnc').value = s.kingMccmnc || 'NULLNULL';\n  $('kingApn').value = s.kingApn || 'UNKNOW';\n  $('kingTypeName').value = s.kingTypeName || 'UNKNOW';\n  $('kingSubtype').value = s.kingSubtype != null ? s.kingSubtype : 0;\n  $('kingExtraInfo').value = s.kingExtraInfo || 'UNKNOW';\n  $('kingCardType').value = s.kingCardType != null ? s.kingCardType : 1;\n  $('kingAutoDirectOnNonCellular').checked = !!s.kingAutoDirectOnNonCellular;\n  syncModeUI();\n  const effective = s.effectiveMode || s.proxyMode || 'custom';\n  const labels = {custom:'自定义代理', direct:'直连（无代理）', kingcard:'王卡代理', tailscale:'Tailscale'};\n  $('effectiveMode').textContent = labels[effective] || effective;\n}\nfunction renderExitNodes(nodes, selectedID) {\n  const sel = $('tailscaleExitNodeID');\n  const prev = sel.value;\n  sel.innerHTML = '';\n  if (!nodes || !nodes.length) {\n    const opt = document.createElement('option');\n    opt.value = '';\n    opt.textContent = '暂无可用 Exit Node';\n    sel.appendChild(opt);\n    return;\n  }\n  nodes.forEach(n => {\n    const opt = document.createElement('option');\n    opt.value = n.ID || n.StableID || '';\n    const name = n.HostName || n.DNSName || n.ID || 'unknown';\n    const ips = (n.TailscaleIPs || []).join(',');\n    opt.textContent = name + (ips ? ' (' + ips + ')' : '');\n    sel.appendChild(opt);\n  });\n  if (selectedID) sel.value = selectedID;\n  else if (prev) sel.value = prev;\n}\nasync function loadTailscale() {\n  const r = await api('/api/tailscale/status');\n  if (r.error) return;\n  $('tsRunning').textContent = r.starting ? '启动中…' : (r.running ? '运行中' : '未运行');\n  $('tsBackendState').textContent = r.backendState || '—';\n  $('tsPort').textContent = r.proxyPort ? String(r.proxyPort) : '—';\n  const authEl = $('tsAuthURL');\n  if (r.authURL) {\n    authEl.textContent = r.authURL;\n    authEl.style.color = '#58a6ff';\n  } else {\n    authEl.textContent = '—';\n  }\n  renderExitNodes(r.exitNodes || [], r.selectedExitNodeID || '');\n  $('tailscaleExitNodeEnabled').checked = !!r.exitNodeEnabled;\n}\nasync function loadStats() {\n  const s = await api('/api/stats');\n  if (s.error) { $('statsMsg').textContent = '统计获取失败: '+s.error; return; }\n  $('net').innerHTML = s.cellular ? \"<span class='badge on'>蜂窝</span>\" : \"<span class='badge off'>Wi-Fi/其他</span>\";\n  $('totalUp').textContent = fmt(s.totalUpload);\n  $('totalDown').textContent = fmt(s.totalDownload);\n  const apps = (s.apps||[]).map(a => a.bundleId+' '+fmt(a.totalUpload)+'↑ '+fmt(a.totalDownload)+'↓').join('<br>') || '—';\n  $('appList').innerHTML = apps;\n  const rows = (s.buckets||[]).slice(-48).reverse().map(b =>\n    '<tr><td>'+fmtTime(b.start)+'</td><td>'+fmt(b.upload)+'</td><td>'+fmt(b.download)+'</td></tr>'\n  ).join('');\n  $('buckets').innerHTML = rows || '<tr><td colspan=3 style=\"text-align:center;color:#8b949e\">暂无数据</td></tr>';\n}\n$('proxyMode').onchange = () => { markDirty(); syncModeUI(); };\n['proxyEnabled','blockNonTcp','debugLogging','showProxyBanner','kingAutoDirectOnNonCellular'].forEach(id => { $(id).addEventListener('change', markDirty); });\n['proxyType','proxyHost','proxyPort','kingPhone','kingQType','kingMccmnc','kingApn','kingTypeName','kingSubtype','kingExtraInfo','kingCardType'].forEach(id => { $(id).addEventListener('input', markDirty); });\nfunction fmtLogTime(ts) {\n  const d = new Date(ts*1000);\n  const p = x => String(x).padStart(2,'0');\n  return p(d.getHours())+':'+p(d.getMinutes())+':'+p(d.getSeconds());\n}\nfunction renderKingLog(log) {\n  const el = $('kingRefreshLog');\n  if (!log.length) { el.textContent = '暂无记录'; return; }\n  el.textContent = log.map(e => {\n    const head = fmtLogTime(e.ts) + ' [' + (e.ok ? '成功' : '失败') + ']'\n      + (e.src ? ' ' + e.src : '') + (e.ms != null ? ' ' + Math.round(e.ms) + 'ms' : '');\n    return head + (e.msg ? '\\n' + e.msg : '');\n  }).join('\\n----------------------------------------\\n');\n}\nlet manualRefreshing = false;\n$('kingRefreshBtn').onclick = async () => {\n  if (manualRefreshing) return;\n  manualRefreshing = true;\n  const btn = $('kingRefreshBtn');\n  btn.disabled = true;\n  $('kingManualResult').textContent = '刷新中…（正在取号，最长约 30 秒，请勿重复点击）';\n  $('kingError').textContent = '刷新中…';\n  try {\n    const r = await api('/api/king/refresh', {method:'POST', body:'{}'});\n    if (r.error) {\n      $('kingManualResult').textContent = '刷新失败: ' + r.error;\n    } else {\n      const log = (r.refreshLog || [])[0];\n      const head = log ? ('本次取号 ' + (log.ok ? '成功' : '失败')\n        + (log.src ? ' · ' + log.src : '')\n        + (log.ms != null ? ' · ' + Math.round(log.ms) + 'ms' : '') + '\\n') : '';\n      $('kingManualResult').textContent = head + ((log && log.msg) || r.lastError || '');\n      $('kingError').textContent = r.lastRefreshSuccess ? '刷新成功' : (r.lastError || '刷新失败');\n    }\n  } catch (e) {\n    $('kingManualResult').textContent = '请求异常: ' + e;\n  } finally {\n    manualRefreshing = false;\n    btn.disabled = false;\n    loadStatus();\n  }\n};\n$('saveConfig').onclick = async () => {\n  const body = {\n    proxyEnabled: $('proxyEnabled').checked,\n    blockNonTcp: $('blockNonTcp').checked,\n    debugLogging: $('debugLogging').checked,\n    showProxyBanner: $('showProxyBanner').checked,\n    proxyMode: $('proxyMode').value,\n    proxyType: $('proxyType').value.trim() || 'http',\n    proxyHost: $('proxyHost').value.trim(),\n    proxyPort: parseInt($('proxyPort').value || '0', 10),\n    kingPhone: $('kingPhone').value.trim() || '18812341234',\n    kingQType: $('kingQType').value.trim() || 'httpcom',\n    kingMccmnc: $('kingMccmnc').value.trim() || 'NULLNULL',\n    kingApn: $('kingApn').value.trim() || 'UNKNOW',\n    kingTypeName: $('kingTypeName').value.trim() || 'UNKNOW',\n    kingSubtype: parseInt($('kingSubtype').value || '0', 10),\n    kingExtraInfo: $('kingExtraInfo').value.trim() || 'UNKNOW',\n    kingCardType: parseInt($('kingCardType').value || '1', 10),\n    kingAutoDirectOnNonCellular: $('kingAutoDirectOnNonCellular').checked,\n    tailscaleHostname: $('tailscaleHostname').value.trim() || 'lc-tailscale',\n    tailscaleAuthKey: $('tailscaleAuthKey').value.trim(),\n    tailscaleControlURL: $('tailscaleControlURL').value.trim(),\n    tailscaleStateDir: $('tailscaleStateDir').value.trim(),\n    tailscaleEphemeral: $('tailscaleEphemeral').checked,\n    tailscaleExitNodeID: $('tailscaleExitNodeID').value || '',\n    tailscaleExitNodeEnabled: $('tailscaleExitNodeEnabled').checked\n  };\n  const r = await api('/api/config', {method:'POST', body:JSON.stringify(body)});\n  if (!r.error) dirty = false;\n  $('cfgMsg').textContent = r.error ? ('保存失败: '+r.error) : '已保存并应用（部分系统组件需重启 App 生效）';\n  loadStatus();\n};\n$('testProxyBtn').onclick = async () => {\n  const sources = [\n    'http://ip.3322.net',\n    'http://ifconfig.me/ip',\n    'http://icanhazip.com',\n    'http://members.3322.org/dyndns/getip',\n    'http://ip-api.com/line/?fields=query',\n    'http://myip.ipip.net'\n  ];\n  $('proxyTestMsg').textContent = '开始并发测试…';\n  $('proxyTestDetail').textContent = '';\n  const results = await Promise.all(sources.map(async (url) => {\n    const r = await api('/api/proxy-test-one', {method:'POST', body: JSON.stringify({url})});\n    const info = r.ip ? ('IP '+r.ip) : ('rc='+(r.rc!=null?r.rc:'?')+(r.body?' '+r.body:''));\n    $('proxyTestDetail').textContent += url + ' -> ' + info + '\\n';\n    return {url, r};\n  }));\n  const found = results.find(x => x.r.ok && x.r.ip);\n  if (found) {\n    $('proxyTestMsg').textContent = '出口 IP: '+found.r.ip+'（'+found.url+'，共测试 '+sources.length+' 个源，并发完成）';\n  } else {\n    $('proxyTestMsg').textContent = '所有 IP 源均失败，请检查代理/转发器';\n  }\n};\n$('copyAuthURL').onclick = () => {\n  const url = $('tsAuthURL').textContent;\n  if (!url || url === '—') return;\n  if (navigator.clipboard && navigator.clipboard.writeText) {\n    navigator.clipboard.writeText(url).then(() => { $('tsCfgMsg').textContent = '登录链接已复制'; });\n  } else {\n    $('tsCfgMsg').textContent = '请手动复制: ' + url;\n  }\n};\n$('saveTailscale').onclick = async () => {\n  const body = {\n    proxyMode: $('proxyMode').value,\n    tailscaleHostname: $('tailscaleHostname').value.trim() || 'lc-tailscale',\n    tailscaleAuthKey: $('tailscaleAuthKey').value.trim(),\n    tailscaleControlURL: $('tailscaleControlURL').value.trim(),\n    tailscaleStateDir: $('tailscaleStateDir').value.trim(),\n    tailscaleEphemeral: $('tailscaleEphemeral').checked,\n    tailscaleExitNodeID: $('tailscaleExitNodeID').value || '',\n    tailscaleExitNodeEnabled: $('tailscaleExitNodeEnabled').checked\n  };\n  const r = await api('/api/config', {method:'POST', body:JSON.stringify(body)});\n  $('tsCfgMsg').textContent = r.error ? ('保存失败: '+r.error) : '已保存并应用';\n  loadStatus();\n};\n$('applyExitNode').onclick = async () => {\n  const id = $('tailscaleExitNodeID').value || '';\n  const enabled = $('tailscaleExitNodeEnabled').checked;\n  const r = await api('/api/tailscale/exit-node', {method:'POST', body: JSON.stringify({id, enabled})});\n  $('tsExitMsg').textContent = r.error ? ('设置失败: '+r.error) : (enabled ? '已启用 Exit Node' : '已关闭 Exit Node');\n  loadTailscale();\n  loadStatus();\n};\n$('resetStats').onclick = async () => {\n  const r = await api('/api/reset-stats', {method:'POST', body:'{}'});\n  $('statsMsg').textContent = r.error ? ('失败: '+r.error) : '统计已清空';\n  loadStats();\n};\nasync function refresh() { await loadStatus(); await loadStats(); await loadTailscale(); }\nsetInterval(refresh, 5000);\nrefresh();\n</script>\n</body>\n</html>\n";
